const $=s=>document.querySelector(s);const money=n=>`NT$ ${n.toLocaleString('zh-TW')}`;let category='全部商品',onlyWish=false;
function load(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let cart=load('mori-cart',[]);if(!Array.isArray(cart))cart=[];cart=cart.filter(i=>products.some(p=>p.id===i.id)&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<=99&&typeof i.color==='string'&&typeof i.size==='string');let storedWish=load('mori-wishlist',[]);let wishlist=new Set(Array.isArray(storedWish)?storedWish.filter(id=>products.some(p=>p.id===id)):[]);
function persist(){try{localStorage.setItem('mori-cart',JSON.stringify(cart));localStorage.setItem('mori-wishlist',JSON.stringify([...wishlist]))}catch{toast('瀏覽器無法儲存，本次操作仍可繼續')}updateCount()}
function updateCount(){const n=cart.reduce((s,i)=>s+i.qty,0);$('#cartCount').textContent=n;$('#cartToggle').setAttribute('aria-label',`開啟購物袋，${n} 件商品`);$('#drawerCount').textContent=`(${n})`}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function render(){const query=$('#search').value.trim().toLowerCase();let list=products.filter(p=>(category==='全部商品'||p.category===category)&&(!onlyWish||wishlist.has(p.id))&&`${p.name}${p.category}${p.material}`.toLowerCase().includes(query));if($('#sort').value==='price-asc')list.sort((a,b)=>a.price-b.price);if($('#sort').value==='price-desc')list.sort((a,b)=>b.price-a.price);$('#resultCount').textContent=`${onlyWish?'我的收藏 · ':''}${list.length} 件選物`;$('#products').innerHTML=list.length?list.map(p=>`<article class="product"><div class="product-visual"><button class="open-product" data-product="${p.id}" aria-label="查看${p.name}"><img src="${p.image}" alt="${p.name}穿搭示意" loading="lazy"></button><span class="product-tag">${p.tag}</span><button class="favorite ${wishlist.has(p.id)?'saved':''}" data-favorite="${p.id}" aria-label="${wishlist.has(p.id)?'取消收藏':'收藏'}${p.name}" aria-pressed="${wishlist.has(p.id)}">${wishlist.has(p.id)?'♥':'♡'}</button><button class="quick-add" data-product="${p.id}">選擇尺寸 ＋</button></div><div class="product-meta"><button class="product-name" data-product="${p.id}">${p.name}</button><span class="price">${money(p.price)}</span></div><div class="product-sub"><span>${p.material}</span><span class="swatches">${p.colors.map(([name,color])=>`<i class="swatch" style="background:${color}" title="${name}"></i>`).join('')}</span></div></article>`).join(''):'<div class="empty">目前沒有符合的商品。<br><br><button class="button" id="emptyReset">瀏覽全部選物 ↗</button></div>';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===category);b.setAttribute('aria-pressed',String(b.dataset.filter===category))});$('#wishToggle').setAttribute('aria-pressed',String(onlyWish));}
function setCategory(value){category=value;onlyWish=false;render()}
function reset(){category='全部商品';onlyWish=false;$('#search').value='';$('#sort').value='featured';render()}
let selection={};
function openProduct(id){const p=products.find(p=>p.id===id);selection={id,size:p.category==='配件'?'F':'M',color:0};const sizes=p.category==='配件'?['F']:['S','M','L'];$('#productDetail').innerHTML=`<div class="detail-layout"><img src="${p.image}" alt="${p.name}"><div class="detail-copy"><div class="eyebrow">MORI / ${p.category}</div><h2>${p.name}</h2><div class="detail-price">${money(p.price)}</div><p class="detail-description">${p.material}。簡潔的線條搭配舒適觸感，輕鬆融入日常穿搭。商品圖片為風格示意，實際規格以正式商品資料為準。</p><div class="option-label">顏色</div><div class="color-options">${p.colors.map(([name],i)=>`<button data-color="${i}" class="${i===0?'selected':''}" aria-pressed="${i===0}">${name}</button>`).join('')}</div><div class="option-label">尺寸</div><div class="size-options">${sizes.map(s=>`<button data-size="${s}" class="${selection.size===s?'selected':''}" aria-pressed="${selection.size===s}">${s}</button>`).join('')}</div><p class="size-help">${p.category==='配件'?'F 為單一尺寸。':'S／M／L 為示範尺碼；請參考尺寸指南。'}</p><button class="button" id="addToCart">加入購物袋 ＋</button><p class="size-help">概念選物商品・尚未提供實際交易</p></div></div>`;$('#productDialog').showModal()}
function addToCart(){const p=products.find(p=>p.id===selection.id);const color=p.colors[selection.color][0];const item=cart.find(i=>i.id===p.id&&i.size===selection.size&&i.color===color);if(item){if(item.qty>=99){toast('單一品項最多 99 件');return}item.qty++}else cart.push({id:p.id,size:selection.size,color,qty:1});persist();$('#productDialog').close();toast('已加入購物袋，喜歡就慢慢穿。')}
function renderCart(){const total=cart.reduce((s,i)=>s+products.find(p=>p.id===i.id).price*i.qty,0);$('#cartItems').innerHTML=cart.length?cart.map((item,index)=>{const p=products.find(p=>p.id===item.id);return `<div class="cart-row"><img src="${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.colors.some(([c])=>c===item.color)?item.color:p.colors[0][0]} / ${['S','M','L','F'].includes(item.size)?item.size:'M'} · ${money(p.price)}</p><div class="quantity-row"><button data-qty="${index}" data-change="-1" aria-label="減少${p.name}數量">−</button><span>${item.qty}</span><button data-qty="${index}" data-change="1" aria-label="增加${p.name}數量">＋</button><button class="remove" data-remove="${index}">移除</button></div></div></div>`}).join(''):'<div class="empty">購物袋還空著。<br><br>把喜歡的日常，慢慢裝進來。<br><br><button class="button" data-close="cartDialog">繼續逛逛 ↗</button></div>';$('#cartSummary').innerHTML=cart.length?`<div class="totals"><span>商品小計</span><strong>${money(total)}</strong></div><button class="button cart-checkout" id="checkout">查看結帳摘要 <span>→</span></button><p class="demo-note">此為示範購物袋，尚未串接金流與物流，不會收款或建立正式訂單。</p>`:'';updateCount()}
const info={shopping:['購物說明','這是一間 MORI 概念商店。你可以瀏覽商品、選擇尺寸與顏色、收藏商品並加入購物袋。','商品、售價、圖片及尺寸均為示範資料。網站尚未提供付款、配送、退換貨或實際訂單服務。'],contact:['聯絡我們','謝謝你對 MORI 的喜愛。此為概念商店，目前尚未設定正式客服管道。','正式營運前，商店管理者可補上客服信箱與服務時間。'],privacy:['隱私說明','購物袋與收藏清單會儲存在你目前瀏覽器的本機儲存空間，重新整理後仍可保留。本站不要求姓名、地址或付款資訊。','頁面使用 Unsplash 圖片與 Google Fonts 字型，載入時瀏覽器會連線至這些外部服務。清除瀏覽器網站資料即可移除本機購物紀錄。']};
function showInfo(type){if(type==='sizes'){$('#infoContent').innerHTML='<h2>尺寸指南</h2><p>以下為示範身形建議，單位為公分。不同品項的正式衣長、胸寬與腰圍尚未設定。</p><table><thead><tr><th>尺寸</th><th>身高參考</th><th>胸圍參考</th></tr></thead><tbody><tr><td>S</td><td>155–160</td><td>80–84</td></tr><tr><td>M</td><td>160–165</td><td>84–88</td></tr><tr><td>L</td><td>165–170</td><td>88–94</td></tr></tbody></table><p>配件 F 為單一尺寸。以上僅為介面示範。</p>'}else{const [title,...paragraphs]=info[type];$('#infoContent').innerHTML=`<h2>${title}</h2>${paragraphs.map(p=>`<p>${p}</p>`).join('')}`}$('#infoDialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.filter){setCategory(b.dataset.filter)}if(b.dataset.category){setCategory(b.dataset.category)}if(b.dataset.product)openProduct(Number(b.dataset.product));if(b.dataset.favorite){const id=Number(b.dataset.favorite);if(wishlist.has(id))wishlist.delete(id);else wishlist.add(id);persist();render()}if(b.dataset.close)document.getElementById(b.dataset.close).close();if(b.dataset.color!==undefined){selection.color=Number(b.dataset.color);document.querySelectorAll('[data-color]').forEach(el=>{const on=el===b;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on))})}if(b.dataset.size){selection.size=b.dataset.size;document.querySelectorAll('[data-size]').forEach(el=>{const on=el===b;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on))})}if(b.id==='addToCart')addToCart();if(b.dataset.qty!==undefined){const index=Number(b.dataset.qty);cart[index].qty=Math.min(99,cart[index].qty+Number(b.dataset.change));if(cart[index].qty<=0)cart.splice(index,1);persist();renderCart()}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);persist();renderCart()}if(b.dataset.info)showInfo(b.dataset.info);if(b.id==='emptyReset')reset();if(b.id==='checkout'){const total=cart.reduce((s,i)=>s+products.find(p=>p.id===i.id).price*i.qty,0);$('#cartDialog').close();$('#infoContent').innerHTML=`<div class="eyebrow">YOUR EVERYDAY PICKS</div><h2>結帳摘要</h2><p>已選擇 ${cart.reduce((s,i)=>s+i.qty,0)} 件商品<br>商品小計：${money(total)}</p><p>這是示範結帳流程，尚未串接付款或物流；不會收取款項，也不會送出正式訂單。你的購物袋已保留。</p><button class="button" data-close="infoDialog">繼續探索 ↗</button>`;$('#infoDialog').showModal()}});
$('#cartToggle').addEventListener('click',()=>{renderCart();$('#cartDialog').showModal()});$('#wishToggle').addEventListener('click',()=>{onlyWish=!onlyWish;category='全部商品';$('#search').value='';render();$('#shop').scrollIntoView()});$('#searchToggle').addEventListener('click',()=>{$('#searchBar').hidden=false;$('#shop').scrollIntoView();$('#search').focus({preventScroll:true})});$('#search').addEventListener('input',render);$('#clearSearch').addEventListener('click',()=>{$('#search').value='';render()});$('#sort').addEventListener('change',render);$('#resetShop').addEventListener('click',reset);document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));render();updateCount();
